css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: var(--loader-size); position: relative; border-radius: 50%; background: color-mix(in srgb, #fff 62%, var(--accent-2)); box-shadow: inset 0 0 0 calc(var(--loader-size) * .05) color-mix(in srgb, #000 20%, var(--accent-2)); }
.loader::after { content: ''; position: absolute; top: 30%; left: 41%; width: 18%; height: 34%; border-radius: 50% 50% 20% 20%; background: color-mix(in srgb, #000 56%, var(--accent-2)); }
.loader .key { position: absolute; z-index: 2; top: 16%; left: calc(50% - var(--loader-size) * .035); width: calc(var(--loader-size) * .07); height: calc(var(--loader-size) * .66); transform-origin: 50% 50%; border-radius: 999px; background: linear-gradient(90deg, color-mix(in srgb, #fff 40%, var(--accent)), var(--accent)); animation: turn-key calc(var(--loader-speed) * 2.4) cubic-bezier(.5, 0, .3, 1) infinite; }
.loader .key::before { content: ''; position: absolute; top: calc(var(--loader-size) * -.14); left: calc(var(--loader-size) * -.06); width: calc(var(--loader-size) * .19); height: calc(var(--loader-size) * .19); border-radius: 50%; border: calc(var(--loader-size) * .034) solid var(--accent); }
.loader .key::after { content: ''; position: absolute; bottom: calc(var(--loader-size) * .03); left: 86%; width: calc(var(--loader-size) * .1); height: calc(var(--loader-size) * .18); background: var(--accent); clip-path: polygon(0 0, 100% 0, 100% 30%, 38% 30%, 38% 58%, 100% 58%, 100% 100%, 0 100%); }
@keyframes turn-key { 0%, 20% { transform: rotate(0deg); } 48%, 70% { transform: rotate(92deg); } 92%, 100% { transform: rotate(0deg); } }
